-- Spells used by the NMS AA set (utils/sql/dynamic_items/nms_aa_tables.sql) in the versions NMS changed them to.
-- Load this with the NMS AA set (rule Custom:NmsAATables); without it those AAs cast stock PEQ spells and
-- behave differently (Holy Shield procs Kinetic Shield IV instead of its Holy Shield rune, and so on).
-- 463 spells. The spells of the optional NMS custom AAs are in nms_aa_custom_spells.sql instead.
-- 24 of them are also used by stock NPCs, items or spell scrolls (among them Ignite Blood, Force Strike, Pogonip,
-- Avalanche, Ice, Scourge, Plague, Lava Bolt, Sicken, See Invisible, Doppelganger and several mount summons),
-- which then get the NMS versions too.
-- Run shared_memory after loading, and players need matching client spell files (spells_us.txt).
SET @OLD_AUTOCOMMIT=@@AUTOCOMMIT, @@AUTOCOMMIT=0;
COMMIT;
SET AUTOCOMMIT=@OLD_AUTOCOMMIT;
